    image_patch = ImagePatch(image)
    bananas = image_patch.find("banana")
    bowls = image_patch.find("bowl")
    strawberries = image_patch.find("strawberry")

    if not bananas or not bowls or not strawberries:
        return image_patch

    # Find the banana that is on the side of a bowl
    for banana in bananas:
        for bowl in bowls:
            if banana.overlaps_with(banana.left, banana.lower, banana.right, bowl.upper) or \
               banana.overlaps_with(banana.left, bowl.lower, banana.right, banana.upper):
                # Now find the bowl that is behind the strawberry
                for bowl_behind in bowls:
                    if is_behind(banana, bowl_behind) and not any(is_in_front_of(strawberry, bowl_behind) for strawberry in strawberries):
                        return banana
    return bananas[0] if bananas else image_patch

